#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OPS = json.loads(zlib.decompress(base64.b64decode('')).decode("utf-8"))

for kind, relative, old, new, expected_count in OPS:
    path = ROOT / relative
    if not path.is_file():
        raise SystemExit(f"missing file: {relative}")
    text = path.read_text(encoding="utf-8")
    actual_count = text.count(old)
    if actual_count != expected_count:
        raise SystemExit(
            f"{relative}: expected {expected_count} replacement target(s), found {actual_count}: {old[:120]!r}"
        )
    path.write_text(text.replace(old, new, expected_count), encoding="utf-8")

print("Applied the post-change FLOC*Loom audit fixes.")
